import 'dart:async';import 'dart:convert';import 'package:http/http.dart' as http;import 'package:razorpay_flutter/razorpay_flutter.dart';import 'package:shared_preferences/shared_preferences.dart';import '../models/models.dart';
class GaonApi{static const String baseUrl=String.fromEnvironment('API_URL',defaultValue:'http://10.0.2.2:8000/api/v1');static const Duration timeout=Duration(seconds:15);static Future<SharedPreferences> get _prefs=>SharedPreferences.getInstance();static Future<bool> hasToken()async=>(await _prefs).getString('token')!=null;static Future<void> saveToken(String t)async=>(await _prefs).setString('token',t);static Future<void> logout()async=>(await _prefs).remove('token');static Future<Map<String,String>> _headers()async{final t=(await _prefs).getString('token');return{'Content-Type':'application/json',if(t!=null)'Authorization':'Bearer $t'};}static dynamic _decode(http.Response r){final b=r.body.isEmpty?null:jsonDecode(r.body);if(r.statusCode<200||r.statusCode>=300){final d=b is Map?b['detail']:null;throw Exception(d is String?d:'Request failed (${r.statusCode})');}return b;}static Future<http.Response> _get(Uri u)async=>http.get(u,headers:await _headers()).timeout(timeout);static Future<http.Response> _post(Uri u,{Object? body})async=>http.post(u,headers:await _headers(),body:body).timeout(timeout);static Future<http.Response> _patch(Uri u,{Object? body})async=>http.patch(u,headers:await _headers(),body:body).timeout(timeout);static Future<http.Response> _delete(Uri u)async=>http.delete(u,headers:await _headers()).timeout(timeout);
static Future<String?> requestOtp(String p)async{final d=_decode(await _post(Uri.parse('$baseUrl/auth/request-otp'),body:jsonEncode({'phone':p}))) as Map<String,dynamic>;return d['dev_otp'];}static Future<void> verifyOtp(String p,String o,String n)async{final d=_decode(await _post(Uri.parse('$baseUrl/auth/verify-otp'),body:jsonEncode({'phone':p,'otp':o,if(n.isNotEmpty)'full_name':n}))) as Map<String,dynamic>;await saveToken(d['access_token']);}static Future<UserModel> me()async=>UserModel.fromJson(_decode(await _get(Uri.parse('$baseUrl/users/me'))));
static Future<List<Village>> villages()async=>(_decode(await _get(Uri.parse('$baseUrl/villages'))) as List).map((e)=>Village.fromJson(e)).toList();static Future<List<StoreModel>> stores([String? v])async{final u=Uri.parse('$baseUrl/stores').replace(queryParameters:v==null?null:{'village_id':v});return(_decode(await _get(u))as List).map((e)=>StoreModel.fromJson(e)).toList();}static Future<List<StoreModel>> nearbyStores(double a,double b,{double radiusKm=15})async{final u=Uri.parse('$baseUrl/stores/nearby').replace(queryParameters:{'lat':'$a','lng':'$b','radius_km':'$radiusKm'});return(_decode(await _get(u))as List).map((e)=>StoreModel.fromJson(e)).toList();}static Future<List<StoreProduct>> storeProducts(String id)async=>(_decode(await _get(Uri.parse('$baseUrl/stores/$id/products')))as List).map((e)=>StoreProduct.fromJson(e)).toList();
static Future<CartModel> cart()async=>CartModel.fromJson(_decode(await _get(Uri.parse('$baseUrl/cart'))));static Future<CartModel> addToCart(String id,{int quantity=1})async=>CartModel.fromJson(_decode(await _post(Uri.parse('$baseUrl/cart/items'),body:jsonEncode({'store_product_id':id,'quantity':quantity}))));static Future<CartModel> removeCartItem(String id)async=>CartModel.fromJson(_decode(await _delete(Uri.parse('$baseUrl/cart/items/$id'))));static Future<CartModel> clearCart()async=>CartModel.fromJson(_decode(await _delete(Uri.parse('$baseUrl/cart'))));
static Future<List<AddressModel>> addresses()async=>(_decode(await _get(Uri.parse('$baseUrl/addresses/me')))as List).map((e)=>AddressModel.fromJson(e)).toList();static Future<AddressModel> createAddress({required String villageId,required String label,required String landmark,String? houseDetails,String? recipientName,String? phone,double? latitude,double? longitude,String? directions,bool isDefault=false})async=>AddressModel.fromJson(_decode(await _post(Uri.parse('$baseUrl/addresses/me'),body:jsonEncode({'village_id':villageId,'label':label,'recipient_name':recipientName,'phone':phone,'house_details':houseDetails,'landmark':landmark,'directions':directions,'latitude':latitude,'longitude':longitude,'is_default':isDefault}))));
static Future<OrderModel> checkout(String a,String p)async=>OrderModel.fromJson(_decode(await _post(Uri.parse('$baseUrl/orders/checkout'),body:jsonEncode({'address_id':a,'payment_method':p}))));static Future<List<OrderModel>> orders()async=>(_decode(await _get(Uri.parse('$baseUrl/orders/me')))as List).map((e)=>OrderModel.fromJson(e)).toList();static Future<Map<String,dynamic>> orderDetail(String id)async=>Map<String,dynamic>.from(_decode(await _get(Uri.parse('$baseUrl/orders/$id'))));static Future<OrderModel> cancelOrder(String id)async=>OrderModel.fromJson(_decode(await _post(Uri.parse('$baseUrl/orders/$id/cancel'))));
static Future<PaymentConfigModel> paymentConfig()async=>PaymentConfigModel.fromJson(_decode(await _get(Uri.parse('$baseUrl/payments/config'))));static Future<PaymentIntentModel> paymentIntent(String id)async=>PaymentIntentModel.fromJson(_decode(await _post(Uri.parse('$baseUrl/payments/orders/$id/intent'))));static Future<void> verifyOnlinePayment({required String paymentAttemptId,required String paymentId,required String signature})async{_decode(await _post(Uri.parse('$baseUrl/payments/verify'),body:jsonEncode({'payment_attempt_id':paymentAttemptId,'razorpay_payment_id':paymentId,'razorpay_signature':signature})));}
static Future<bool> openRazorpayCheckout(OrderModel o)async{final c=await paymentConfig();if(!c.enabled||c.keyId==null)throw Exception('Online payments are not configured yet. Use cash on delivery.');final i=await paymentIntent(o.id),u=await me(),x=Completer<bool>(),r=Razorpay();Future<void> ok(PaymentSuccessResponse p)async{try{if(p.paymentId==null||p.signature==null)throw Exception('Incomplete payment');await verifyOnlinePayment(paymentAttemptId:i.paymentAttemptId,paymentId:p.paymentId!,signature:p.signature!);if(!x.isCompleted)x.complete(true);}catch(_){if(!x.isCompleted)x.complete(false);}finally{r.clear();}}void no(dynamic _){if(!x.isCompleted)x.complete(false);r.clear();}r.on(Razorpay.EVENT_PAYMENT_SUCCESS,ok);r.on(Razorpay.EVENT_PAYMENT_ERROR,no);r.on(Razorpay.EVENT_EXTERNAL_WALLET,no);r.open({'key':i.keyId,'amount':i.amountSubunits,'currency':i.currency,'name':'GaonOne','description':'Order ${o.orderNumber}','order_id':i.providerOrderId,'prefill':{'contact':u.phone,'name':u.fullName??''}});return x.future.timeout(const Duration(minutes:5),onTimeout:(){r.clear();return false;});}
static Future<List<NotificationEventModel>> notifications()async=>(_decode(await _get(Uri.parse('$baseUrl/notifications/me')))as List).map((e)=>NotificationEventModel.fromJson(e)).toList();static Future<List<OrderModel>> merchantOrders()async=>(_decode(await _get(Uri.parse('$baseUrl/merchant/orders')))as List).map((e)=>OrderModel.fromJson(e)).toList();static Future<OrderModel> updateMerchantOrder(String id,String s)async=>OrderModel.fromJson(_decode(await _patch(Uri.parse('$baseUrl/merchant/orders/$id/status'),body:jsonEncode({'status':s}))));
static Future<Map<String,dynamic>?> merchantProfile()async{try{return Map<String,dynamic>.from(_decode(await _get(Uri.parse('$baseUrl/merchants/me'))));}catch(e){if(e.toString().contains('404'))return null;rethrow;}}static Future<Map<String,dynamic>> applyMerchant(String name,{String? gstin})async=>Map<String,dynamic>.from(_decode(await _post(Uri.parse('$baseUrl/merchants/apply'),body:jsonEncode({'business_name':name,'gstin':gstin}))));static Future<List<StoreModel>> myStores()async=>(_decode(await _get(Uri.parse('$baseUrl/stores/mine')))as List).map((e)=>StoreModel.fromJson(e)).toList();static Future<StoreModel> createStore({required String villageId,required String name,required String slug,String? landmark,String? phone})async=>StoreModel.fromJson(_decode(await _post(Uri.parse('$baseUrl/stores'),body:jsonEncode({'village_id':villageId,'name':name,'slug':slug,'landmark':landmark,'phone':phone,'delivery_enabled':true,'pickup_enabled':true}))));
static Future<List<DeliveryTaskModel>> availableDeliveryTasks()async=>(_decode(await _get(Uri.parse('$baseUrl/delivery/tasks/available')))as List).map((e)=>DeliveryTaskModel.fromJson(e)).toList();static Future<List<DeliveryTaskModel>> myDeliveryTasks()async=>(_decode(await _get(Uri.parse('$baseUrl/delivery/tasks/me')))as List).map((e)=>DeliveryTaskModel.fromJson(e)).toList();static Future<DeliveryModel> claimDelivery(String id)async=>DeliveryModel.fromJson(_decode(await _post(Uri.parse('$baseUrl/delivery/$id/claim'))));static Future<DeliveryModel> updateDelivery(String id,String s)async=>DeliveryModel.fromJson(_decode(await _patch(Uri.parse('$baseUrl/delivery/$id/status'),body:jsonEncode({'status':s}))));}
